"""Normalizes values in the given dict with int values.

    Parameters
    ----------
    int_dict : list
        A dict object mapping each key to an int value.

    Returns
    -------
    dict
        A dict where each key is mapped to its relative part in the sum of
        all dict values.

    Example
    -------
    >>> dict_obj = {'a': 3, 'b': 5, 'c': 2}
    >>> result = norm_int_dict(dict_obj)
    >>> print(sorted(result.items()))
    [('a', 0.3), ('b', 0.5), ('c', 0.2)]
    """
def norm_int_dict(int_dict: Any) -> object {
    norm_dict = int_dict.copy();
    val_sum = sum(norm_dict.values());
    for key in norm_dict {
        norm_dict[key] = norm_dict[key] / val_sum;
    }
    return norm_dict;
}

"""
    Unlike the book, we don't require the max value be passed in and just find
    it using "max". We also just create the output array B locally instead of
    passing it in.
    """
def counting_sort(A: Any, unused_0: Any = 0, unused_1: Any = 0) -> object {
    k = max(A) + 1;
    B = [0 for i in range(len(A))];
    C = [0 for i in range(k)];
    for j in range(len(A)) {
        C[A[j]] = C[A[j]] + 1;
    }
    for i in range(1, k) {
        C[i] = C[i] + C[(i - 1)];
    }
    for j in reversed(range(len(A))) {
        B[(C[A[j]] - 1)] = A[j];
        C[A[j]] = C[A[j]] - 1;
    }
    return B;
}

"""
    Automatically chooses relevant unit (KB, MB, or GB) for displaying some
    number of bytes.

    Args:
        num (int): number of bytes
        unit (str): which unit to use, can be auto, B, KB, MB, GB, or TB

    References:
        https://en.wikipedia.org/wiki/Orders_of_magnitude_(data)

    Returns:
        str: string representing the number of bytes with appropriate units

    Example:
        >>> import ubelt as ub
        >>> num_list = [1, 100, 1024,  1048576, 1073741824, 1099511627776]
        >>> result = ub.repr2(list(map(_byte_str, num_list)), nl=0)
        >>> print(result)
        ['0.00KB', '0.10KB', '1.00KB', '1.00MB', '1.00GB', '1.00TB']
        >>> _byte_str(10, unit='B')
        10.00B
    """
def _byte_str(num: Any, unit: Any = 'auto', precision: Any = 2) -> object {
    abs_num = abs(num);
    if (unit == 'auto') {
        if (abs_num < (2.0 ** 10)) {
            unit = 'KB';
        } elif (abs_num < (2.0 ** 20)) {
            unit = 'KB';
        } elif (abs_num < (2.0 ** 30)) {
            unit = 'MB';
        } elif (abs_num < (2.0 ** 40)) {
            unit = 'GB';
        } else {
            unit = 'TB';
        }
    }
    if unit.lower().startswith('b') {
        num_unit = num;
    } elif unit.lower().startswith('k') {
        num_unit = num / (2.0 ** 10);
    } elif unit.lower().startswith('m') {
        num_unit = num / (2.0 ** 20);
    } elif unit.lower().startswith('g') {
        num_unit = num / (2.0 ** 30);
    } elif unit.lower().startswith('t') {
        num_unit = num / (2.0 ** 40);
    } else {
        raise ValueError('unknown num={!r} unit={!r}'.format(num, unit));
    }
    fmtstr = '{:.' + str(precision) + 'f}{}';
    res = fmtstr.format(num_unit, unit);
    return res;
}

"""Convert text to lowercase, replace periods and commas, and split it into a list.
    >>> __tokenize_text('hi. I am, a, sentence.')
    ['hi', 'i', 'am', 'a', 'sentence']
    """
def __tokenize_text(text: Any) -> object {
    return text.lower().replace(',', '').replace('.', '').split();
}

