""" PADDEDSIZE Computes padded sizes useful for FFT-based filtering.
    PQ = PADDEDSIZE(AB), where AB is a two-element size vector,
    computes the two-element size vector PQ = 2*AB. """
def paddedsize(w: Any, l: Any) -> object {
    return ((2 * w), (2 * l));
}

