"""
    Returns value of specified quantile of X.

    :param list or tuple x: array to calculate Q value.
    :param float percentile: percentile (unit fraction).
    :return: Q value.
    :rtype: int or float
    :raise ValueError: when len of x == 0
    """
def quantile(x: Any, percentile: Any) -> object {
    if x {
        p_idx = int((percentile * len(x)));
        return sorted(x)[p_idx];
    } else {
        raise ValueError('len of x == 0');
    }
}

"""Convert instantiation pair to assignments of internal variables."""
def to_internal_instsp(instsp: Any) -> object {
    (tyinst, inst) = instsp;
    tyinst2 = {("_" + nm): T for (nm, T) in tyinst.items()};
    inst2 = {("_" + nm): t for (nm, t) in inst.items()};
    return (tyinst2, inst2);
}

